package com.bank.review.model;

// One finding recorded against one pillar during the review.
public class ReviewFinding {
    private final Pillar pillar;
    private final RiskLevel risk;
    private final String issue;        // what is wrong
    private final String remediation;  // what to do about it

    public ReviewFinding(Pillar pillar, RiskLevel risk, String issue, String remediation) {
        this.pillar = pillar;
        this.risk = risk;
        this.issue = issue;
        this.remediation = remediation;
    }

    public Pillar getPillar() { return pillar; }
    public RiskLevel getRisk() { return risk; }
    public String getIssue() { return issue; }
    public String getRemediation() { return remediation; }

    public boolean isActionable() {
        return risk != RiskLevel.NONE;
    }
}
