package com.bank.review.review;

import com.bank.review.model.ReviewFinding;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Collects findings as the reviewers walk each pillar.
public class WellArchitectedReview {
    private static final Logger log = Logger.getLogger(WellArchitectedReview.class.getName());
    private final String workload;
    private final List<ReviewFinding> findings = new ArrayList<>();

    public WellArchitectedReview(String workload) {
        this.workload = workload;
    }

    public void record(ReviewFinding finding) {
        findings.add(finding);
        if (finding.isActionable()) {
            log.warning(() -> "[" + finding.getPillar() + "] " + finding.getRisk()
                    + " risk: " + finding.getIssue());
        } else {
            log.info(() -> "[" + finding.getPillar() + "] compliant — no finding");
        }
    }

    public List<ReviewFinding> getFindings() {
        return findings;
    }

    public String getWorkload() {
        return workload;
    }
}
