package com.bank.review.plan;

import com.bank.review.model.ReviewFinding;
import java.util.Comparator;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

// Turns raw findings into a prioritized, actionable plan (HIGH first).
public class RemediationPlanner {
    private static final Logger log = Logger.getLogger(RemediationPlanner.class.getName());

    public List<ReviewFinding> prioritize(List<ReviewFinding> findings) {
        List<ReviewFinding> plan = findings.stream()
                .filter(ReviewFinding::isActionable)
                .sorted(Comparator.comparingInt(f -> f.getRisk().getRank()))
                .collect(Collectors.toList());

        log.info(() -> "Prioritized remediation plan has " + plan.size() + " item(s)");
        int order = 1;
        for (ReviewFinding f : plan) {
            final int position = order++;
            log.info(() -> position + ". [" + f.getRisk() + "] " + f.getPillar()
                    + " — fix: " + f.getRemediation());
        }
        return plan;
    }
}
