package com.bank.review;

import com.bank.review.model.Pillar;
import com.bank.review.model.ReviewFinding;
import com.bank.review.model.RiskLevel;
import com.bank.review.plan.RemediationPlanner;
import com.bank.review.review.WellArchitectedReview;
import java.util.logging.Logger;

// Runnable demo: reviewing the realtime payments service across six pillars.
public class ReviewApplication {
    private static final Logger log = Logger.getLogger(ReviewApplication.class.getName());

    public static void main(String[] args) {
        WellArchitectedReview review = new WellArchitectedReview("realtime-payments");
        log.info("=== National Bank of India — Well-Architected review: realtime-payments ===");

        // Problem 1: manual deploys, no runbooks → high Operational Excellence risk.
        review.record(new ReviewFinding(Pillar.OPERATIONAL_EXCELLENCE, RiskLevel.HIGH,
                "manual deployment, no runbooks",
                "adopt IaC + automated CD pipeline, write on-call runbooks"));

        // Problem 2: single AZ, no tested failover → high Reliability risk.
        review.record(new ReviewFinding(Pillar.RELIABILITY, RiskLevel.HIGH,
                "single-AZ database, recovery never tested",
                "multi-AZ with automated failover, define RTO/RPO, run DR game-days"));

        // Problem 3: peak-sized 24x7 → medium Cost risk (also helps Sustainability).
        review.record(new ReviewFinding(Pillar.COST_OPTIMIZATION, RiskLevel.MEDIUM,
                "peak-provisioned 24x7 despite daytime-skewed traffic",
                "enable auto-scaling, right-size, schedule scale-down off-peak"));

        // Problem 4: least privilege + encryption + logging → Security compliant.
        review.record(new ReviewFinding(Pillar.SECURITY, RiskLevel.NONE,
                "least privilege, encryption in transit/at rest, audit logging on",
                "no action — maintain controls"));

        RemediationPlanner planner = new RemediationPlanner();
        planner.prioritize(review.getFindings());
    }
}
